/**
 * Redis-MongoDB Change Stream Nodes for Node-RED
 * Author: Node-RED Community
 * 
 * This module provides nodes for:
 * 1. Reading MongoDB change streams and publishing to Redis streams
 * 2. Creating Redis consumer groups and processing stream messages
 * 
 * Features:
 * - Resume token persistence in Redis with atomic transactions
 * - Distributed locking for concurrency control
 * - Start from "now" if no resume tokens exist
 * - Custom message format for easy TypeScript integration
 */

/**
 * @typedef {Object} MongoDBChangeEvent
 * @property {string} collection - Collection name
 * @property {"insert"|"update"|"delete"|"replace"} change - Type of change operation
 * @property {Object|null} before - Document state before change (null for inserts)
 * @property {Object|null} after - Document state after change (null for deletes)
 * @property {string} changedAt - ISO timestamp of when change occurred
 * @property {Object} [metadata] - Additional metadata (documentKey, updateDescription, etc.)
 */

/**
 * MongoDBChangeEvent interface is now globally available in TypeScript function nodes
 * via the Monaco Editor type definitions
 */

module.exports = function(RED) {
    "use strict";
    
    const { MongoClient } = require('mongodb');
    const { createClient } = require('redis');
    const { v4: uuidv4 } = require('uuid');

    // Redis Configuration Node
    function RedisConfigNode(n) {
        RED.nodes.createNode(this, n);
        
        this.host = n.host || 'localhost';
        this.port = n.port || 6379;
        this.database = n.database || 0;
        this.password = n.password;
        this.username = n.username;
        this.tls = n.tls || false;
        
        var node = this;
        
        this.connect = function() {
            const config = {
                socket: {
                    host: node.host,
                    port: node.port,
                    tls: node.tls
                },
                database: node.database
            };
            
            if (node.password) {
                config.password = node.password;
            }
            
            if (node.username) {
                config.username = node.username;
            }
            
            return createClient(config);
        };
    }
    
    RED.nodes.registerType("redis-config", RedisConfigNode);

    // MongoDB Configuration Node
    function MongoDBConfigNode(n) {
        RED.nodes.createNode(this, n);
        
        this.uri = n.uri || 'mongodb://localhost:27017';
        this.database = n.database;
        this.collection = n.collection;
        this.options = n.options || {};
        
        var node = this;
        
        this.connect = function() {
            try {
                const options = typeof node.options === 'string' ? JSON.parse(node.options) : node.options;
                return new MongoClient(node.uri, options);
            } catch (err) {
                throw new Error("Invalid MongoDB options JSON: " + err.message);
            }
        };
    }
    
    RED.nodes.registerType("mongodb-config", MongoDBConfigNode);

    // Redis-MongoDB Change Stream Reader Node
    function RedisMongoDBChangeStreamNode(n) {
        RED.nodes.createNode(this, n);
        
        this.mongoConfig = RED.nodes.getNode(n.mongoConfig);
        this.redisConfig = RED.nodes.getNode(n.redisConfig);
        this.streamName = n.streamName || 'mongodb-changes';
        this.lockKey = n.lockKey || 'mongodb-changestream-lock';
        this.lockTimeout = parseInt(n.lockTimeout) || 60000; // 60 seconds
        this.pipeline = n.pipeline || [];
        this.maxStreams = parseInt(n.maxStreams) || 1000;
        
        var node = this;
        var mongoClient = null;
        var redisClient = null;
        var changeStream = null;
        var lockInterval = null;
        var isLocked = false;
        
        if (!this.mongoConfig) {
            node.error("MongoDB configuration missing");
            return;
        }
        
        if (!this.redisConfig) {
            node.error("Redis configuration missing");
            return;
        }
        
        async function acquireLock() {
            try {
                const lockValue = uuidv4();
                const result = await redisClient.set(
                    node.lockKey,
                    lockValue,
                    'PX',
                    node.lockTimeout,
                    'NX'
                );
                
                if (result === 'OK') {
                    isLocked = true;
                    node.lockValue = lockValue;
                    node.status({fill: "green", shape: "dot", text: "Lock acquired"});
                    return true;
                } else {
                    isLocked = false;
                    node.status({fill: "yellow", shape: "ring", text: "Waiting for lock"});
                    return false;
                }
            } catch (err) {
                node.error("Error acquiring lock: " + err.message);
                return false;
            }
        }
        
        async function renewLock() {
            if (!isLocked || !node.lockValue) return false;
            
            try {
                const script = `
                    if redis.call("get", KEYS[1]) == ARGV[1] then
                        return redis.call("pexpire", KEYS[1], ARGV[2])
                    else
                        return 0
                    end
                `;
                
                const result = await redisClient.eval(script, {
                    keys: [node.lockKey],
                    arguments: [node.lockValue, node.lockTimeout.toString()]
                });
                
                return result === 1;
            } catch (err) {
                node.error("Error renewing lock: " + err.message);
                return false;
            }
        }
        
        async function releaseLock() {
            if (!isLocked || !node.lockValue) return;
            
            try {
                const script = `
                    if redis.call("get", KEYS[1]) == ARGV[1] then
                        return redis.call("del", KEYS[1])
                    else
                        return 0
                    end
                `;
                
                await redisClient.eval(script, {
                    keys: [node.lockKey],
                    arguments: [node.lockValue]
                });
                
                isLocked = false;
                node.lockValue = null;
                node.status({fill: "grey", shape: "ring", text: "Lock released"});
            } catch (err) {
                node.error("Error releasing lock: " + err.message);
            }
        }
        
        async function startChangeStream() {
            try {
                const db = mongoClient.db(node.mongoConfig.database);
                const collection = db.collection(node.mongoConfig.collection);
                
                let pipeline = [];
                if (node.pipeline && Array.isArray(node.pipeline)) {
                    pipeline = node.pipeline;
                } else if (typeof node.pipeline === 'string' && node.pipeline.trim()) {
                    try {
                        pipeline = JSON.parse(node.pipeline);
                    } catch (err) {
                        node.warn("Invalid pipeline JSON, using empty pipeline: " + err.message);
                        pipeline = [];
                    }
                }
                
                const options = {
                    fullDocument: 'updateLookup',
                    fullDocumentBeforeChange: 'required'  // Try 'required' instead of 'whenAvailable'
                };
                
                changeStream = collection.watch(pipeline, options);
                
                changeStream.on('change', async (change) => {
                    if (!isLocked) return;
                    
                    try {
                        node.debug("Processing change event:", change.operationType);
                        
                        // Create standardized message format
                        const mongoChangeEvent = {
                            collection: node.mongoConfig.collection,
                            change: change.operationType,
                            before: null,
                            after: null,
                            changedAt: new Date().toISOString(),
                            metadata: {}
                        };

                        node.debug("Created initial mongoChangeEvent");

                        // Safely add metadata fields
                        try {
                            mongoChangeEvent.metadata = {
                                documentKey: change.documentKey || null,
                                updateDescription: change.updateDescription || null,
                                ns: change.ns || null
                            };
                            node.debug("Added metadata successfully");
                        } catch (err) {
                            node.warn("Error creating metadata, using empty object: " + err.message);
                            mongoChangeEvent.metadata = {};
                        }
                        
                        // Set before/after based on operation type
                        try {
                            switch (change.operationType) {
                                case 'insert':
                                    mongoChangeEvent.before = null;
                                    mongoChangeEvent.after = change.fullDocument || null;
                                    break;
                                                            case 'update':
                                mongoChangeEvent.before = change.fullDocumentBeforeChange || null;
                                mongoChangeEvent.after = change.fullDocument || null;
                                
                                // Debug why before might be null
                                if (!change.fullDocumentBeforeChange) {
                                    node.warn("fullDocumentBeforeChange is null - this might be normal if the document was just created or MongoDB doesn't support it");
                                }
                                break;
                                case 'replace':
                                    mongoChangeEvent.before = change.fullDocumentBeforeChange || null;
                                    mongoChangeEvent.after = change.fullDocument || null;
                                    break;
                                case 'delete':
                                    mongoChangeEvent.before = change.fullDocumentBeforeChange || null;
                                    mongoChangeEvent.after = null;
                                    break;
                                default:
                                    // For other operations, just use fullDocument
                                    mongoChangeEvent.after = change.fullDocument || null;
                            }
                            node.debug("Set before/after values successfully");
                        } catch (err) {
                            node.error("Error setting before/after values: " + err.message);
                            throw err;
                        }
                        
                        // Create Redis stream entry with safe string conversion
                        // Redis requires ALL field values to be strings
                        let metadataString = 'null';
                        try {
                            metadataString = mongoChangeEvent.metadata ? JSON.stringify(mongoChangeEvent.metadata) : 'null';
                            node.debug("Stringified metadata successfully");
                        } catch (err) {
                            node.warn("Error stringifying metadata, using 'null': " + err.message);
                            metadataString = 'null';
                        }

                        let beforeString = 'null';
                        let afterString = 'null';
                        
                        try {
                            beforeString = mongoChangeEvent.before ? JSON.stringify(mongoChangeEvent.before) : 'null';
                            node.debug("Stringified before successfully");
                        } catch (err) {
                            node.warn("Error stringifying before, using 'null': " + err.message);
                            beforeString = 'null';
                        }
                        
                        try {
                            afterString = mongoChangeEvent.after ? JSON.stringify(mongoChangeEvent.after) : 'null';
                            node.debug("Stringified after successfully");
                        } catch (err) {
                            node.warn("Error stringifying after, using 'null': " + err.message);
                            afterString = 'null';
                        }

                        const streamEntry = {
                            collection: String(mongoChangeEvent.collection || ''),
                            change: String(mongoChangeEvent.change || ''),
                            before: beforeString,
                            after: afterString,
                            changedAt: String(mongoChangeEvent.changedAt || ''),
                            metadata: metadataString
                        };
                        
                        node.debug("Created streamEntry:", JSON.stringify(streamEntry, null, 2));
                        
                        try {
                            await redisClient.xAdd(node.streamName, '*', streamEntry);
                            node.debug("Successfully added to Redis stream");
                        } catch (err) {
                            node.error("Error in xAdd: " + err.message);
                            node.error("Stream name: " + node.streamName);
                            node.error("Stream entry: " + JSON.stringify(streamEntry, null, 2));
                            throw err;
                        }
                        
                        // Trim stream to max length
                        try {
                            const maxLen = parseInt(node.maxStreams) || 1000;
                            await redisClient.xTrim(node.streamName, 'MAXLEN', '~', maxLen);
                            node.debug("Successfully trimmed stream");
                        } catch (err) {
                            node.warn("Error trimming stream: " + err.message);
                            // Don't throw, trimming is not critical
                        }
                        
                        node.status({fill: "green", shape: "dot", text: `Published ${change.operationType}`});
                        
                    } catch (err) {
                        node.error("Error publishing to Redis stream: " + err.message);
                        node.error("Change event: " + JSON.stringify(change, null, 2));
                        node.error("Stack trace: " + err.stack);
                    }
                });
                
                changeStream.on('error', (err) => {
                    node.error("Change stream error: " + err.message);
                    node.status({fill: "red", shape: "ring", text: "Change stream error"});
                });
                
                node.status({fill: "green", shape: "dot", text: "Change stream active"});
                
            } catch (err) {
                node.error("Error starting change stream: " + err.message);
                node.status({fill: "red", shape: "ring", text: "Change stream error"});
            }
        }
        
        async function initialize() {
            try {
                // Connect to MongoDB
                mongoClient = node.mongoConfig.connect();
                await mongoClient.connect();
                node.log("Connected to MongoDB");
                
                // Connect to Redis
                redisClient = node.redisConfig.connect();
                await redisClient.connect();
                node.log("Connected to Redis");
                
                // Try to acquire lock
                const lockAcquired = await acquireLock();
                
                if (lockAcquired) {
                    await startChangeStream();
                    
                    // Set up lock renewal
                    lockInterval = setInterval(async () => {
                        const renewed = await renewLock();
                        if (!renewed) {
                            node.warn("Failed to renew lock, stopping change stream");
                            if (changeStream) {
                                changeStream.close();
                            }
                            isLocked = false;
                        }
                    }, Math.floor(node.lockTimeout / 2));
                } else {
                    // Retry acquiring lock every 5 seconds
                    setTimeout(async () => {
                        const lockAcquired = await acquireLock();
                        if (lockAcquired) {
                            await startChangeStream();
                        }
                    }, 5000);
                }
                
            } catch (err) {
                node.error("Initialization error: " + err.message);
                node.status({fill: "red", shape: "ring", text: "Connection error"});
            }
        }
        
        // No input handling needed - this is a source node
        
        // Handle node shutdown
        this.on('close', async function(done) {
            if (lockInterval) {
                clearInterval(lockInterval);
            }
            
            if (changeStream) {
                changeStream.close();
            }
            
            await releaseLock();
            
            if (mongoClient) {
                await mongoClient.close();
            }
            
            if (redisClient) {
                await redisClient.quit();
            }
            
            done();
        });
        
        // Initialize on startup
        initialize();
    }
    
    RED.nodes.registerType("redis-mongodb-changestream", RedisMongoDBChangeStreamNode);

    // Redis Stream Worker Node
    function RedisStreamWorkerNode(n) {
        RED.nodes.createNode(this, n);
        
        this.redisConfig = RED.nodes.getNode(n.redisConfig);
        this.streamName = n.streamName || 'mongodb-changes';
        this.consumerGroup = n.consumerGroup || 'default-group';
        this.consumerName = n.consumerName || `consumer-${uuidv4().substring(0, 8)}`;
        this.blockTimeout = parseInt(n.blockTimeout) || 1000;
        this.maxRetries = parseInt(n.maxRetries) || 3;
        this.batchSize = parseInt(n.batchSize) || 1;
        
        var node = this;
        var redisClient = null;
        var isRunning = false;
        var processingLoop = null;
        
        if (!this.redisConfig) {
            node.error("Redis configuration missing");
            return;
        }
        
        async function createConsumerGroup() {
            try {
                await redisClient.xGroupCreate(
                    node.streamName,
                    node.consumerGroup,
                    '0',
                    { MKSTREAM: true }
                );
                node.log(`Created consumer group: ${node.consumerGroup}`);
            } catch (err) {
                if (err.message.includes('BUSYGROUP')) {
                    node.log(`Consumer group already exists: ${node.consumerGroup}`);
                } else {
                    throw err;
                }
            }
        }
        
        async function processMessages() {
            if (!isRunning) return;
            
            try {
                // Read from consumer group
                const messages = await redisClient.xReadGroup(
                    node.consumerGroup,
                    node.consumerName,
                    [
                        {
                            key: node.streamName,
                            id: '>'
                        }
                    ],
                    {
                        COUNT: node.batchSize,
                        BLOCK: node.blockTimeout
                    }
                );
                
                if (messages && messages.length > 0) {
                    for (const streamData of messages) {
                        for (const message of streamData.messages) {
                            try {
                                const messageData = message.message;
                                
                                // Parse the standardized MongoDB change event
                                const mongoChangeEvent = {
                                    collection: messageData.collection,
                                    change: messageData.change,
                                    before: (messageData.before && messageData.before !== 'null') ? JSON.parse(messageData.before) : null,
                                    after: (messageData.after && messageData.after !== 'null') ? JSON.parse(messageData.after) : null,
                                    changedAt: messageData.changedAt,
                                    metadata: (messageData.metadata && messageData.metadata !== 'null') ? JSON.parse(messageData.metadata) : null
                                };
                                
                                const msg = {
                                    payload: mongoChangeEvent,
                                    messageId: message.id,
                                    streamName: node.streamName,
                                    consumerGroup: node.consumerGroup,
                                    consumerName: node.consumerName,
                                    ack: async function() {
                                        try {
                                            await redisClient.xAck(node.streamName, node.consumerGroup, message.id);
                                            node.log(`Acknowledged message: ${message.id}`);
                                        } catch (err) {
                                            node.error(`Failed to acknowledge message ${message.id}: ${err.message}`);
                                        }
                                    }
                                };
                                
                                // Send message to output
                                node.send(msg);
                                
                                node.status({
                                    fill: "green",
                                    shape: "dot",
                                    text: `Processing ${mongoChangeEvent.change} on ${mongoChangeEvent.collection}`
                                });
                                
                            } catch (err) {
                                node.error("Error processing message: " + err.message);
                                node.error("Message data: " + JSON.stringify(messageData, null, 2));
                            }
                        }
                    }
                }
                
                // Continue processing
                setImmediate(processMessages);
                
            } catch (err) {
                if (err.message.includes('NOGROUP')) {
                    node.warn("Consumer group does not exist, recreating...");
                    await createConsumerGroup();
                    setImmediate(processMessages);
                } else {
                    node.error("Error reading from stream: " + err.message);
                    node.status({fill: "red", shape: "ring", text: "Stream error"});
                    
                    // Retry after delay
                    setTimeout(processMessages, 5000);
                }
            }
        }
        
        async function initialize() {
            try {
                // Connect to Redis
                redisClient = node.redisConfig.connect();
                await redisClient.connect();
                node.log("Connected to Redis");
                
                // Create consumer group
                await createConsumerGroup();
                
                // Start processing messages
                isRunning = true;
                node.status({fill: "green", shape: "dot", text: "Ready"});
                
                processMessages();
                
            } catch (err) {
                node.error("Initialization error: " + err.message);
                node.status({fill: "red", shape: "ring", text: "Connection error"});
            }
        }
        
        // No input handling needed - this is a source node
        
        // Handle node shutdown
        this.on('close', async function(done) {
            isRunning = false;
            
            if (processingLoop) {
                clearTimeout(processingLoop);
            }
            
            if (redisClient) {
                await redisClient.quit();
            }
            
            done();
        });
        
        // Initialize on startup
        initialize();
    }
    
    RED.nodes.registerType("redis-stream-worker", RedisStreamWorkerNode);

    // Redis Stream Ack Node
    function RedisStreamAckNode(n) {
        RED.nodes.createNode(this, n);
        
        this.ackMode = n.ackMode || 'auto'; // 'auto', 'manual', 'conditional'
        this.condition = n.condition || ''; // JSONata expression for conditional ack
        
        var node = this;
        
        this.on('input', async function(msg, send, done) {
            try {
                let shouldAck = false;
                
                // Determine if we should acknowledge based on mode
                switch (node.ackMode) {
                    case 'auto':
                        shouldAck = true;
                        break;
                        
                    case 'manual':
                        // Only ack if msg.shouldAck is explicitly true
                        shouldAck = msg.shouldAck === true;
                        break;
                        
                    case 'conditional':
                        // Use JSONata expression to determine if we should ack
                        if (node.condition) {
                            try {
                                const expr = RED.util.prepareJSONataExpression(node.condition, node);
                                shouldAck = RED.util.evaluateJSONataExpression(expr, msg) === true;
                            } catch (err) {
                                node.warn("Error evaluating condition, not acknowledging: " + err.message);
                                shouldAck = false;
                            }
                        }
                        break;
                }
                
                // Attempt to acknowledge
                if (shouldAck && msg.ack && typeof msg.ack === 'function') {
                    try {
                        await msg.ack();
                        node.status({fill: "green", shape: "dot", text: "Acknowledged"});
                        node.log(`Acknowledged message ${msg.messageId || 'unknown'}`);
                        
                        // Add ack info to message
                        msg.acknowledged = true;
                        msg.acknowledgedAt = new Date().toISOString();
                        
                    } catch (err) {
                        node.error("Error acknowledging message: " + err.message);
                        node.status({fill: "red", shape: "ring", text: "Ack failed"});
                        
                        // Add error info to message
                        msg.acknowledged = false;
                        msg.ackError = err.message;
                        
                        // Pass message through even if ack fails
                    }
                } else if (!msg.ack) {
                    node.warn("Message does not have an ack function - not a Redis stream message?");
                    node.status({fill: "yellow", shape: "ring", text: "No ack function"});
                } else if (!shouldAck) {
                    node.status({fill: "grey", shape: "dot", text: "Not acknowledged"});
                    msg.acknowledged = false;
                    msg.ackReason = "Condition not met";
                }
                
                // Always pass the message through (pass-through behavior)
                send(msg);
                done();
                
            } catch (err) {
                node.error("Error in ack node: " + err.message);
                node.status({fill: "red", shape: "ring", text: "Error"});
                done(err);
            }
        });
        
        // Set initial status
        node.status({fill: "grey", shape: "ring", text: "Ready"});
    }
    
    RED.nodes.registerType("redis-stream-ack", RedisStreamAckNode);
}; 